#include <stdio.h>

#define HEIGHT 3

int main() {
    for (int row = 1; row <= HEIGHT; row++) {
        for (int i = 0; i < HEIGHT - row; i++) {
            printf(" ");
        }
        for (int i = 0; i < 2 * row - 1; i++) {
            printf("*");
        }
        printf("\n");
    }
    return 0;
}
